{
  "summary": "风险复核延续中性立场，不改变 Phase 3/4 的方向与概率框架，核心新增在执行层：QQQ 维持不进场上限约束，SOXX 保持可执行偏空但上限更严格。整体新增约束优先放在高波动下的回撤放大控制而非方向性加码。",
  "confidence": 0.0,
  "authoritative_fields": {
    "stance": "neutral",
    "unique_risk_contribution": "SOXX 对利率、流动性与行业事件的共同共振敏感度高于 QQQ；其财报与行业事件可逆性导致下行放大更明显，QQQ 则更多受宏观分歧与流动性确认缺失驱动。",
    "disagreement_with_prior": "与上游方向保持一致：QQQ 继续观望/保持，不做新增方向性；SOXX 维持偏空执行性，但明确上限与风控闸门，非与上游相反。",
    "no_new_information": false,
    "recommended_adjustment": "执行层将 QQQ 的仓位上限固定为 0.00，SOXX 设定 0.30 上限，并以事件-量能/财报核验与政策转折为主触发条件；组合层维持高现金缓冲，优先降低可变净风险暴露，不新增可交易对冲品种。",
    "per_asset": {
      "QQQ": {
        "position_cap_pct": 0.0,
        "max_drawdown_pct": null,
        "stop_type": "none",
        "risk_off_trigger": "未来1-2日政策表态未出现可交易鸽化转折，且QQQ在关键数据或事件后出现放量下行。",
        "rebalance_trigger": "出现可验证鸽化且高贝塔未回撤时允许提升进场讨论；若利率预期继续抬升并同步下破则维持无新增进场；财报群超预期持续且未破坏宏观结构时中性减弱。",
        "review_window": null,
        "constraint_confidence": null
      },
      "SOXX": {
        "position_cap_pct": 0.3,
        "max_drawdown_pct": null,
        "stop_type": "none",
        "risk_off_trigger": "财报未改善现金流/库存且 SOXX 无放量修复，且利率预期仍偏紧时偏空概率上移。",
        "rebalance_trigger": "关键财报出现订单、毛利、库存改善并伴随 SOXX 放量跟随则可降级/撤销偏空执行；宏观利率预期明显放松且风险偏好上转则上行触发概率上移；财报文本与成交量等缺口补齐后重估触发强度。",
        "review_window": null,
        "constraint_confidence": null
      }
    },
    "cash_hedge_recommendation": "维持高现金比例以吸收政策与波动共振下的突发回撤；不新增具体对冲品种，目标是减少可变净风险暴露。",
    "portfolio_risk_triggers": [
      "VIX context-only 上行且政策口径分歧放大时，成长与半导体回撤弹性上升，优先强化SOXX与QQQ触发门槛。",
      "利率预期偏鹰+流动性缓冲不足时，QQQ 与 SOXX 的宏观共振增强，需优先执行仓位约束与风险放大管理。",
      "SOXX 对利率与行业事件共振的高敏感度意味着组合层风险更先于 SOXX 侧显现。"
    ]
  },
  "details": [
    {
      "ticker": "QQQ",
      "evidence": "role explicitly sets position_cap_pct=0.00 and states no新增方向性头寸；风险约束强调缺失分钟级事件-价格闭环导致短线执行风险高。",
      "evidence_type": "direct"
    },
    {
      "ticker": "SOXX",
